"use server";

import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import bcrypt from "bcryptjs";
import { getAuthUser } from "@/lib/auth";

export async function updateProfile(name: string, email: string, department?: string, phone?: string) {
    try {
        const user = await getAuthUser();
        if (!user) return { error: "Unauthorized" };

        // Check email uniqueness (exclude current user)
        if (email !== user.email) {
            const existing = await prisma.user.findUnique({ where: { email } });
            if (existing) return { error: "อีเมลนี้ถูกใช้งานแล้ว" };
        }

        await prisma.user.update({
            where: { id: user.id },
            data: {
                name,
                email,
                department: department || null,
                phone: phone || null,
            }
        });
        revalidatePath("/settings");
        return { success: true };
    } catch (err: unknown) {
        console.error("updateProfile error:", err);
        return { error: "เกิดข้อผิดพลาดในการบันทึกข้อมูล" };
    }
}

export async function changePassword(currentPassword: string, newPassword: string) {
    const authUser = await getAuthUser();
    if (!authUser) throw new Error("Unauthorized");

    // Fetch user with password hash
    const user = await prisma.user.findUnique({ where: { id: authUser.id } });
    if (!user) throw new Error("User not found");

    // Verify current password
    let isCurrentValid = false;
    if (user.password.startsWith("$2a$") || user.password.startsWith("$2b$")) {
        isCurrentValid = await bcrypt.compare(currentPassword, user.password);
    } else {
        // Legacy plaintext comparison
        isCurrentValid = user.password === currentPassword;
    }

    if (!isCurrentValid) {
        return { error: "รหัสผ่านปัจจุบันไม่ถูกต้อง" };
    }

    // Validate new password
    if (newPassword.length < 6) {
        return { error: "รหัสผ่านใหม่ต้องมีอย่างน้อย 6 ตัวอักษร" };
    }

    // Hash and save
    const hashedPassword = await bcrypt.hash(newPassword, 10);
    await prisma.user.update({
        where: { id: authUser.id },
        data: { password: hashedPassword }
    });

    return { success: true };
}

import { supabase } from "@/lib/supabase";

export async function uploadAvatar(formData: FormData) {
    try {
        const user = await getAuthUser();
        if (!user) return { error: "Unauthorized" };

        const file = formData.get("file") as File;
        if (!file) return { error: "No file uploaded" };

        // Check if it's an image
        if (!file.type.startsWith("image/")) {
            return { error: "File is not an image" };
        }

        const bytes = await file.arrayBuffer();
        const buffer = Buffer.from(bytes);

        // Generate unique filename
        const ext = file.name.split(".").pop();
        const uniqueId = `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
        const fileName = `${user.id}-${uniqueId}.${ext}`;

        // Upload to Supabase Storage
        const { data, error } = await supabase.storage
            .from('avatars')
            .upload(fileName, buffer, {
                contentType: file.type,
                upsert: true
            });

        if (error) {
            console.error("Supabase storage error:", error);
            return { error: "อัปโหลดรูปล้มเหลว ตรวจสอบว่าสร้าง Bucket 'avatars' แล้วหรือยัง" };
        }

        // Get public URL
        const { data: publicUrlData } = supabase.storage
            .from('avatars')
            .getPublicUrl(fileName);

        const avatarUrl = publicUrlData.publicUrl;

        // Update user
        await prisma.user.update({
            where: { id: user.id },
            data: { avatarUrl }
        });

        revalidatePath("/settings");
        return { avatarUrl };
    } catch (err: unknown) {
        console.error("uploadAvatar error:", err);
        return { error: "เกิดข้อผิดพลาดในการอัปโหลดรูปภาพ" };
    }
}

"use client";

import { useState, useTransition } from "react";
import { Check, X, Loader2 } from "lucide-react";

type Props = {
    userId: string;
    userName: string;
};

async function approveUser(userId: string) {
    const res = await fetch("/api/admin/approve", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId, action: "approve" }),
    });
    return res.json();
}

async function rejectUser(userId: string) {
    const res = await fetch("/api/admin/approve", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId, action: "reject" }),
    });
    return res.json();
}

export default function ApprovalActions({ userId, userName }: Props) {
    const [isPending, startTransition] = useTransition();
    const [done, setDone] = useState<"approved" | "rejected" | null>(null);
    const [confirmReject, setConfirmReject] = useState(false);

    const handleApprove = () => {
        startTransition(async () => {
            await approveUser(userId);
            setDone("approved");
        });
    };

    const handleReject = () => {
        if (!confirmReject) {
            setConfirmReject(true);
            setTimeout(() => setConfirmReject(false), 3000);
            return;
        }
        startTransition(async () => {
            await rejectUser(userId);
            setDone("rejected");
        });
    };

    if (done === "approved") {
        return (
            <span className="text-xs font-bold text-emerald-600 bg-emerald-50 px-3 py-1.5 rounded-xl border border-emerald-200">
                ✓ อนุมัติแล้ว
            </span>
        );
    }
    if (done === "rejected") {
        return (
            <span className="text-xs font-bold text-rose-600 bg-rose-50 px-3 py-1.5 rounded-xl border border-rose-200">
                ✗ ปฏิเสธแล้ว
            </span>
        );
    }

    return (
        <div className="flex items-center gap-2 shrink-0">
            <button
                onClick={handleApprove}
                disabled={isPending}
                className="flex items-center gap-1.5 px-4 py-2 text-xs font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 hover:bg-emerald-100 rounded-xl transition-all disabled:opacity-60 shadow-2xs"
            >
                {isPending ? <Loader2 size={13} className="animate-spin" /> : <Check size={13} />}
                อนุมัติ
            </button>
            <button
                onClick={handleReject}
                disabled={isPending}
                className={`flex items-center gap-1.5 px-4 py-2 text-xs font-bold rounded-xl border transition-all disabled:opacity-60 shadow-2xs ${
                    confirmReject
                        ? "text-white bg-rose-600 border-rose-700 hover:bg-rose-700 animate-pulse"
                        : "text-rose-600 bg-rose-50 border-rose-200 hover:bg-rose-100"
                }`}
            >
                <X size={13} />
                {confirmReject ? "ยืนยันปฏิเสธ?" : "ปฏิเสธ"}
            </button>
        </div>
    );
}

import { prisma } from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth-options";
import { redirect } from "next/navigation";
import Link from "next/link";
import { ArrowLeft, UserCheck, Clock, Building2, Phone } from "lucide-react";
import ApprovalActions from "@/app/admin/approvals/ApprovalActions";

export default async function ApprovalsPage() {
    const session = await getServerSession(authOptions);
    const role = (session?.user as any)?.role;
    if (role !== "ADMIN") redirect("/403");

    const pendingUsers = await prisma.user.findMany({
        where: { isApproved: false },
        orderBy: { createdAt: "desc" },
    });

    return (
        <div className="max-w-4xl mx-auto space-y-6 pb-12">
            {/* Header */}
            <div className="bg-white border border-slate-200/80 rounded-3xl shadow-xs p-6 md:p-8 flex items-center gap-4">
                <Link href="/admin" className="p-2.5 hover:bg-slate-100 rounded-2xl text-slate-500 border border-slate-200/60">
                    <ArrowLeft size={18} />
                </Link>
                <div className="p-3.5 bg-amber-50 text-amber-600 rounded-2xl border border-amber-100/80">
                    <UserCheck size={26} />
                </div>
                <div>
                    <h1 className="text-2xl font-extrabold text-slate-800 tracking-tight">Pending Approvals</h1>
                    <p className="text-xs text-slate-500 mt-1">อนุมัติหรือปฏิเสธผู้ใช้งานใหม่ที่รอการอนุมัติ — {pendingUsers.length} รายการ</p>
                </div>
            </div>

            {pendingUsers.length === 0 ? (
                <div className="bg-white border border-slate-200/80 rounded-3xl p-16 text-center">
                    <UserCheck size={48} className="mx-auto mb-4 text-emerald-400 opacity-60" />
                    <p className="text-slate-600 font-semibold text-sm">ไม่มีผู้ใช้งานรอการอนุมัติ</p>
                    <p className="text-slate-400 text-xs mt-1">ผู้ใช้ใหม่ที่ลงทะเบียนจะปรากฏที่นี่</p>
                </div>
            ) : (
                <div className="space-y-3">
                    {pendingUsers.map((user) => (
                        <div key={user.id} className="bg-white border border-slate-200/80 rounded-2xl shadow-xs p-5 flex flex-col sm:flex-row sm:items-center gap-4 hover:shadow-md transition-shadow">
                            {/* Avatar */}
                            <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-amber-400 to-orange-500 flex items-center justify-center text-white text-lg font-extrabold shrink-0 shadow-md shadow-amber-500/20">
                                {user.name.charAt(0).toUpperCase()}
                            </div>

                            {/* User Info */}
                            <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-2 flex-wrap">
                                    <h3 className="text-sm font-bold text-slate-800">{user.name}</h3>
                                    <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-100 text-amber-700 border border-amber-200">
                                        รอการอนุมัติ
                                    </span>
                                </div>
                                <p className="text-xs text-slate-500 mt-0.5">{user.email}</p>
                                <div className="flex items-center gap-4 mt-1.5 flex-wrap">
                                    {user.department && (
                                        <span className="text-[11px] text-slate-400 flex items-center gap-1">
                                            <Building2 size={11} /> {user.department}
                                        </span>
                                    )}
                                    {user.phone && (
                                        <span className="text-[11px] text-slate-400 flex items-center gap-1">
                                            <Phone size={11} /> {user.phone}
                                        </span>
                                    )}
                                    <span className="text-[11px] text-slate-400 flex items-center gap-1">
                                        <Clock size={11} /> {new Date(user.createdAt).toLocaleString("th-TH")}
                                    </span>
                                </div>
                            </div>

                            {/* Actions */}
                            <ApprovalActions userId={user.id} userName={user.name} />
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth-options";
import { redirect } from "next/navigation";
import { getSystemStats, getAdminLogs } from "@/app/actions/admin";
import { FolderKanban, Users, AlertCircle, CheckSquare, Shield, ClipboardList, Bell, UserCheck } from "lucide-react";
import Link from "next/link";
import { prisma } from "@/lib/prisma";

const ACTION_LABELS: Record<string, { label: string; color: string }> = {
    ROLE_CHANGE:    { label: "Role Changed",    color: "bg-violet-100 text-violet-700" },
    TOGGLE_ACTIVE:  { label: "Active Toggle",   color: "bg-amber-100 text-amber-700" },
    RESET_PASSWORD: { label: "Password Reset",  color: "bg-rose-100 text-rose-700" },
    CREATE_USER:    { label: "User Created",    color: "bg-emerald-100 text-emerald-700" },
    APPROVE_USER:   { label: "User Approved",   color: "bg-teal-100 text-teal-700" },
    REJECT_USER:    { label: "User Rejected",   color: "bg-orange-100 text-orange-700" },
};

export default async function AdminPage() {
    const session = await getServerSession(authOptions);
    const role = (session?.user as any)?.role;
    if (role !== "ADMIN") redirect("/403");

    const [stats, adminLogs, adminUsers, pendingApprovals] = await Promise.all([
        getSystemStats(),
        getAdminLogs(30),
        prisma.user.findMany({ select: { id: true, name: true } }),
        prisma.user.count({ where: { isApproved: false } }),
    ]);

    const userMap = Object.fromEntries(adminUsers.map(u => [u.id, u.name]));

    const statCards = [
        { label: "Total Projects",      value: stats.totalProjects,  icon: FolderKanban, color: "from-emerald-500 to-green-600", bg: "bg-emerald-50",  text: "text-emerald-700" },
        { label: "Total Users",          value: stats.totalUsers,     icon: Users,         color: "from-violet-500 to-teal-600", bg: "bg-violet-50", text: "text-violet-700" },
        { label: "Pending Approvals",    value: pendingApprovals,     icon: UserCheck,     color: "from-amber-500 to-orange-500", bg: "bg-amber-50",  text: "text-amber-700" },
        { label: "Open Issues",          value: stats.openIssues,     icon: AlertCircle,   color: "from-rose-500 to-red-600", bg: "bg-rose-50",    text: "text-rose-700" },
        { label: "Pending Tasks",        value: stats.pendingTasks,   icon: CheckSquare,   color: "from-amber-500 to-orange-500", bg: "bg-amber-50",  text: "text-amber-700" },
    ];

    return (
        <div className="max-w-6xl mx-auto space-y-7 pb-12">
            {/* Header */}
            <div className="bg-white border border-slate-200/80 rounded-3xl shadow-xs p-6 md:p-8 flex items-center gap-4">
                <div className="p-3.5 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100/80">
                    <Shield size={28} />
                </div>
                <div>
                    <h1 className="text-2xl font-extrabold text-slate-800 tracking-tight">Admin Control Panel</h1>
                    <p className="text-xs text-slate-500 mt-1">ระบบจัดการผู้ใช้งานและภาพรวมทั้งหมดของระบบ</p>
                </div>
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                {statCards.map((card) => {
                    const Icon = card.icon;
                    return (
                        <div key={card.label} className="bg-white border border-slate-200/80 rounded-2xl shadow-xs p-5 hover:shadow-md transition-shadow">
                            <div className={`w-11 h-11 rounded-xl ${card.bg} flex items-center justify-center mb-3`}>
                                <Icon size={22} className={card.text} />
                            </div>
                            <div className="text-3xl font-extrabold text-slate-800">{card.value}</div>
                            <div className="text-xs font-semibold text-slate-500 mt-0.5">{card.label}</div>
                        </div>
                    );
                })}
