import { NextRequest } from "next/server";
import { getToken } from "next-auth/jwt";
import { prisma } from "@/lib/prisma";

export async function GET(req: NextRequest) {
    const token = await getToken({ req });
    if (!token?.sub) {
        return new Response("Unauthorized", { status: 401 });
    }
    const userId = token.sub;

    const encoder = new TextEncoder();

    const stream = new ReadableStream({
        async start(controller) {
            let lastSeenTime = new Date(Date.now() - 3000); // 3 seconds before connection start
            let isClosed = false;
            let tickCount = 0;

            const send = (data: object) => {
                if (isClosed) return;
                try {
                    controller.enqueue(encoder.encode(`data: ${JSON.stringify(data)}\n\n`));
                } catch {
                    isClosed = true;
                }
            };

            const sendPing = () => {
                if (isClosed) return;
                try {
                    controller.enqueue(encoder.encode(`: ping\n\n`));
                } catch {
                    isClosed = true;
                }
            };

            // Fast helper to get unread map in a single SQL query
            const fetchUnreadMap = async () => {
                const rows = await prisma.$queryRaw<{ chatRoomId: string; count: number }[]>`
                    SELECT m."chatRoomId", COUNT(*)::int AS count
                    FROM "ChatMessage" m
                    INNER JOIN "ChatMember" cm ON cm."chatRoomId" = m."chatRoomId"
                    WHERE cm."userId" = ${userId}
                      AND m."senderId" != ${userId}
                      AND m."createdAt" > cm."lastReadAt"
                    GROUP BY m."chatRoomId"
                `;
                const map: Record<string, number> = {};
                let total = 0;
                for (const r of rows) {
                    map[r.chatRoomId] = r.count;
                    total += r.count;
                }
                return { map, total };
            };

            // Initial poll: sends complete initial status
            const initialPoll = async () => {
                try {
                    const { map: roomUnreadMap, total: totalUnread } = await fetchUnreadMap();

                    // Fetch latest message per room
                    const memberships = await prisma.chatMember.findMany({
                        where: { userId },
                        select: {
                            chatRoomId: true,
                            chatRoom: {
                                select: {
                                    messages: {
                                        orderBy: { createdAt: "desc" },
                                        take: 1,
                                        select: {
                                            id: true,
                                            body: true,
                                            senderId: true,
                                            createdAt: true,
                                            attachmentUrl: true,
                                            sender: {
                                                select: { name: true },
                                            },
                                        },
                                    },
                                },
                            },
                        },
                    });

                    const roomLatestMessages: Record<string, any> = {};
                    for (const m of memberships) {
                        if (m.chatRoom?.messages?.length > 0) {
                            const latest = m.chatRoom.messages[0];
                            roomLatestMessages[m.chatRoomId] = {
                                id: latest.id,
                                body: latest.body || (latest.attachmentUrl ? "[ไฟล์แนบ]" : ""),
                                senderId: latest.senderId,
                                senderName: latest.sender?.name,
                                createdAt: latest.createdAt,
                            };
                        }
                    }

                    send({
                        totalUnread,
                        roomUnreadMap,
                        roomLatestMessages,
                        newMessages: [],
                        timestamp: Date.now(),
                    });
                } catch (e) {
                    // Ignore initial error
                }
            };

            // Lightweight delta poll: only runs 1 indexed query when idle
            const deltaPoll = async () => {
                if (isClosed) return;
                tickCount++;

                try {
                    // Query for ANY new messages in rooms the user belongs to since lastSeenTime
                    const newMessages = await prisma.chatMessage.findMany({
                        where: {
                            chatRoom: {
                                members: { some: { userId } }
                            },
                            createdAt: { gt: lastSeenTime }
                        },
                        orderBy: { createdAt: "asc" },
                        select: {
                            id: true,
                            chatRoomId: true,
                            body: true,
                            attachmentUrl: true,
                            attachmentName: true,
                            attachmentType: true,
                            attachmentSize: true,
                            senderId: true,
                            createdAt: true,
                            sender: {
                                select: {
                                    id: true,
                                    name: true,
                                    avatarUrl: true,
                                    email: true,
                                    role: true,
                                }
                            }
                        }
                    });

                    if (newMessages.length > 0) {
                        lastSeenTime = newMessages[newMessages.length - 1].createdAt;

                        // Fetch updated unread counts
                        const { map: roomUnreadMap, total: totalUnread } = await fetchUnreadMap();

                        // Build updated latest message snippet for affected rooms
                        const roomLatestMessages: Record<string, any> = {};
                        for (const msg of newMessages) {
                            roomLatestMessages[msg.chatRoomId] = {
                                id: msg.id,
                                body: msg.body || (msg.attachmentUrl ? "[ไฟล์แนบ]" : ""),
                                senderId: msg.senderId,
                                senderName: msg.sender.name,
                                createdAt: msg.createdAt,
                            };
                        }

                        send({
                            totalUnread,
                            roomUnreadMap,
                            roomLatestMessages,
                            newMessages,
                            timestamp: Date.now(),
                        });
                    } else if (tickCount % 5 === 0) {
                        // Periodic heartbeat (every ~10-12s) to ensure connection stays active and unread is synced
                        const { map: roomUnreadMap, total: totalUnread } = await fetchUnreadMap();
                        send({
                            totalUnread,
                            roomUnreadMap,
                            newMessages: [],
                            timestamp: Date.now(),
                        });
                    } else {
                        sendPing();
                    }
                } catch {
                    // Transient DB read error, send ping
                    sendPing();
                }
            };

            await initialPoll();

            // Poll every 2.5 seconds with lightweight query
            const interval = setInterval(deltaPoll, 2500);

            // Cleanup when client disconnects
            req.signal.addEventListener("abort", () => {
                isClosed = true;
                clearInterval(interval);
                try {
                    controller.close();
                } catch {
                    // already closed
                }
            });
        },
    });

    return new Response(stream, {
        headers: {
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-cache, no-transform",
            "Connection": "keep-alive",
        },
    });
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getAuthUser } from '@/lib/auth';

// Sanitize a CSV cell to prevent CSV injection attacks.
// Fields that start with =, +, -, @, TAB, or CR are prefixed with a single quote.
function sanitizeCsvCell(value: string): string {
    if (/^[=+\-@\t\r]/.test(value)) return `'${value}`;
    return value;
}

function csvRow(...cells: string[]): string {
    return cells.map(c => `"${sanitizeCsvCell(c.replace(/"/g, '""'))}"`).join(',') + '\n';
}

export async function GET(
    request: Request,
    { params }: { params: Promise<{ projectId: string }> }
) {
    // Auth check
    const user = await getAuthUser();
    if (!user) return new NextResponse("Unauthorized", { status: 401 });

    const { projectId } = await params;

    // Project existence check
    const project = await prisma.project.findUnique({
        where: { id: projectId },
        include: {
            developers: { select: { id: true } },
            requirements: {
                where: { deletedAt: null },
                include: {
                    uatCases: {
                        where: { deletedAt: null },
                        include: {
                            issues: { where: { deletedAt: null } }
                        }
                    }
                }
            }
        }
    });

    if (!project) return new NextResponse("Project not found", { status: 404 });

    // Ownership / membership check — only project owner, assigned devs, or ADMIN can export
    const isOwner = project.ownerId === user.id;
    const isDev = project.developers.some(d => d.id === user.id);
    const isAdmin = user.role === "ADMIN";

    if (!isOwner && !isDev && !isAdmin) {
        return new NextResponse("Forbidden — you are not a member of this project", { status: 403 });
    }

    const { searchParams } = new URL(request.url);
    const format = searchParams.get('format'); // 'csv' (default) or 'xlsx'

    if (format === 'xlsx') {
        return buildXlsxResponse(project);
    }

    return buildCsvResponse(project);
}

// ── CSV ─────────────────────────────────────────────────────────────────────

function buildCsvResponse(project: any) {
    // BOM for Excel Thai charset compatibility
    let csv = '\uFEFF';
    csv += csvRow('Req Code', 'Requirement Title', 'UAT Code', 'UAT Title', 'UAT Status',
        'Issue Code', 'Issue Title', 'Issue Status', 'Severity');

    for (const req of project.requirements) {
        if (req.uatCases.length === 0) {
            csv += csvRow(req.reqCode, req.title, '-', '-', '-', '-', '-', '-', '-');
        } else {
            for (const uat of req.uatCases) {
                if (uat.issues.length === 0) {
                    csv += csvRow(req.reqCode, req.title, uat.uatCode, uat.title, uat.status, '-', '-', '-', '-');
                } else {
                    for (const issue of uat.issues) {
                        csv += csvRow(req.reqCode, req.title, uat.uatCode, uat.title, uat.status,
                            issue.issueCode, issue.title, issue.status, issue.severity);
                    }
                }
            }
        }
    }

    return new NextResponse(csv, {
        headers: {
            'Content-Type': 'text/csv; charset=utf-8',
            'Content-Disposition': `attachment; filename="traceability_${project.code}.csv"`,
        },
    });
}

// ── XLSX ─────────────────────────────────────────────────────────────────────

async function buildXlsxResponse(project: any) {
    const ExcelJS = (await import('exceljs')).default;
    const wb = new ExcelJS.Workbook();
    wb.creator = 'PM Control Center';
    const ws = wb.addWorksheet('Traceability Matrix');

    const headerFill = {
        type: 'pattern' as const, pattern: 'solid' as const,
        fgColor: { argb: 'FF4F46E5' }  // emerald-600
    };
    const headerFont = { color: { argb: 'FFFFFFFF' }, bold: true, size: 11 };

    ws.columns = [
        { header: 'Req Code',          key: 'reqCode',    width: 14 },
        { header: 'Requirement Title', key: 'reqTitle',   width: 36 },
        { header: 'UAT Code',          key: 'uatCode',    width: 14 },
        { header: 'UAT Title',         key: 'uatTitle',   width: 36 },
        { header: 'UAT Status',        key: 'uatStatus',  width: 16 },
        { header: 'Issue Code',        key: 'issueCode',  width: 14 },
        { header: 'Issue Title',       key: 'issueTitle', width: 36 },
        { header: 'Issue Status',      key: 'issueStatus',width: 16 },
        { header: 'Severity',          key: 'severity',   width: 12 },
    ];

    // Style header row
    ws.getRow(1).eachCell(cell => {
        cell.fill = headerFill;
        cell.font = headerFont;
        cell.alignment = { vertical: 'middle', horizontal: 'center' };
    });

    const STATUS_COLORS: Record<string, string> = {
        Passed: 'FF10B981', Failed: 'FFF43F5E', Pending: 'FF94A3B8',
        Open: 'FFF43F5E', Resolved: 'FF10B981', Closed: 'FF6B7280',
        'In Progress': 'FFF59E0B', Critical: 'FFBE123C',
        High: 'FFF43F5E', Medium: 'FFF59E0B', Low: 'FF94A3B8',
    };

    for (const req of project.requirements) {
        if (req.uatCases.length === 0) {
            ws.addRow({ reqCode: req.reqCode, reqTitle: req.title, uatCode: '-', uatTitle: '-', uatStatus: '-', issueCode: '-', issueTitle: '-', issueStatus: '-', severity: '-' });
        } else {
            for (const uat of req.uatCases) {
                if (uat.issues.length === 0) {
                    const r = ws.addRow({ reqCode: req.reqCode, reqTitle: req.title, uatCode: uat.uatCode, uatTitle: uat.title, uatStatus: uat.status, issueCode: '-', issueTitle: '-', issueStatus: '-', severity: '-' });
                    applyStatusColor(r, 'uatStatus', uat.status, STATUS_COLORS);
                } else {
                    for (const issue of uat.issues) {
                        const r = ws.addRow({ reqCode: req.reqCode, reqTitle: req.title, uatCode: uat.uatCode, uatTitle: uat.title, uatStatus: uat.status, issueCode: issue.issueCode, issueTitle: issue.title, issueStatus: issue.status, severity: issue.severity });
                        applyStatusColor(r, 'uatStatus', uat.status, STATUS_COLORS);
                        applyStatusColor(r, 'issueStatus', issue.status, STATUS_COLORS);
                        applyStatusColor(r, 'severity', issue.severity, STATUS_COLORS);
                    }
                }
            }
        }
    }

    const buf = Buffer.from(await wb.xlsx.writeBuffer());
    return new NextResponse(buf, {
        headers: {
            'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'Content-Disposition': `attachment; filename="traceability_${project.code}.xlsx"`,
        },
    });
}

function applyStatusColor(row: any, key: string, value: string, colorMap: Record<string, string>) {
    const col = row.getCell(key);
    const color = colorMap[value];
    if (color) {
        col.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: color } };
        col.font = { color: { argb: 'FFFFFFFF' }, bold: true };
    }
    col.alignment = { horizontal: 'center', vertical: 'middle' };
}

import { NextRequest, NextResponse } from "next/server";
import { getToken } from "next-auth/jwt";
import { prisma } from "@/lib/prisma";

export async function GET(req: NextRequest) {
    const token = await getToken({ req });
    if (!token?.sub) {
        return NextResponse.json(
            { unreadNotificationsCount: 0, unreadNotifications: [], unreadChatCount: 0, pendingApprovalsCount: 0 },
            { status: 401 }
        );
    }
    const userId = token.sub;
    const role = (token as any)?.role || "USER";

    try {
        // Parallel fetch notifications, indexed unread chat count, and (if admin) pending approvals in 1 round-trip
        const queries: [Promise<any>, Promise<any>, Promise<number>?] = [
            prisma.notification.findMany({
                where: { userId, isRead: false },
                orderBy: { createdAt: "desc" },
                take: 10,
                select: { id: true, title: true, message: true, link: true, createdAt: true }
            }),
            prisma.$queryRaw<{ count: number }[]>`
                SELECT COUNT(*)::int AS count
                FROM "ChatMessage" m
                INNER JOIN "ChatMember" cm ON cm."chatRoomId" = m."chatRoomId"
                WHERE cm."userId" = ${userId}
                  AND m."senderId" != ${userId}
                  AND m."createdAt" > cm."lastReadAt"
            `
        ];

        if (role === "ADMIN") {
            queries.push(prisma.user.count({ where: { isApproved: false } }));
        }

        const [notifications, chatResult, pendingApprovalsCount = 0] = await Promise.all(queries);
        const unreadChatCount = chatResult[0]?.count ?? 0;

        return NextResponse.json(
            {
                unreadNotificationsCount: notifications.length,
                unreadNotifications: notifications,
                unreadChatCount,
                pendingApprovalsCount,
            },
            {
                headers: {
                    "Cache-Control": "private, no-cache, no-store, must-revalidate",
                },
            }
        );
    } catch (error) {
        console.error("Error fetching badges:", error);
        return NextResponse.json(
            { unreadNotificationsCount: 0, unreadNotifications: [], unreadChatCount: 0, pendingApprovalsCount: 0 },
            { status: 500 }
        );
    }
}

import CalendarView from "@/components/CalendarView";
import { prisma } from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth-options";

export default async function CalendarPage() {
    const session = await getServerSession(authOptions);
    const role = (session?.user as any)?.role || "USER";
    const userId = (session?.user as any)?.id;

    // 1. กรองงาน (Tasks) ตามสิทธิ์ (เฉพาะที่ยังไม่ถูกลบ และมีกำหนดวันส่ง)
    let roleTaskCondition: any = {};
    if (role === "DEV") {
        roleTaskCondition = { assigneeId: userId }; // DEV เห็นเฉพาะงานตัวเอง
    } else if (role === "PM") {
        roleTaskCondition = {
            OR: [
                { assigneeId: userId },             // งานส่วนตัว & งานที่ได้รับมอบหมาย
                { project: { ownerId: userId } }    // งานของทุกคนในโปรเจกต์ที่ตัวเองเป็นเจ้าของ
            ]
        };
    }

    const taskCondition = {
        deletedAt: null,
        ...roleTaskCondition
    };

    // 2. กรองโปรเจกต์สำหรับ Dropdown สร้างงาน
    let projectCondition: any = {};
    if (role === "DEV") {
        projectCondition = { developers: { some: { id: userId } } };
    } else if (role === "PM") {
        projectCondition = { ownerId: userId };
    }

    // Parallel fetch tasks and projects concurrently in a single round-trip
    const [tasks, projects] = await Promise.all([
        prisma.task.findMany({
            where: taskCondition,
            select: {
                id: true,
                title: true,
                dueDate: true,
                isCompleted: true,
                project: {
                    select: { id: true, name: true, code: true }
                },
                assignee: {
                    select: { id: true, name: true }
                }
            }
        }),
        prisma.project.findMany({
            where: projectCondition,
            select: {
                id: true,
                name: true,
                code: true
            },
            orderBy: { name: 'asc' }
        })
    ]);

    return (
        <div className="max-w-7xl mx-auto space-y-6 h-full flex flex-col">
            <div className="flex items-center gap-3">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800">Calendar</h1>
                    <p className="text-gray-500 text-sm mt-1">
                        ปฏิทินแสดงกำหนดการและงานที่ต้องรับผิดชอบ
                    </p>
                </div>
            </div>

            <div className="flex-1">
                {/* ส่งข้อมูล tasks, projects และ role เข้าไปใน CalendarView */}
                <CalendarView tasks={tasks} projects={projects} userRole={role} currentUserId={userId} />
            </div>
        </div>
    );
}

