                </form>

                {/* Register link */}
                <div className="text-center mt-6 pt-5 border-t border-slate-100">
                    <p className="text-sm text-slate-500">
                        ยังไม่มีบัญชี?{" "}
                        <Link href="/register" className="text-emerald-600 font-bold hover:text-emerald-700 hover:underline transition-colors">
                            สมัครสมาชิก
                        </Link>
                    </p>
                </div>
            </div>
        </div>
    );
}

import { prisma } from "@/lib/prisma";
import { notFound } from "next/navigation";
import Link from "next/link";
import { ArrowLeft, Trash2, RotateCcw, AlertTriangle } from "lucide-react";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth-options";
import TrashActions from "@/components/TrashActions";

export default async function TrashPage({ params }: { params: Promise<{ id: string }> }) {
    const { id } = await params;

    const session = await getServerSession(authOptions);
    const userRole = (session?.user as any)?.role || "";

    if (userRole === "DEV") {
        return (
            <div className="max-w-2xl mx-auto py-20 text-center">
                <AlertTriangle size={48} className="mx-auto mb-4 text-amber-400 opacity-60" />
                <p className="text-slate-600 font-semibold">ไม่มีสิทธิ์เข้าถึงถังขยะ</p>
            </div>
        );
    }

    const project = await prisma.project.findUnique({ where: { id } });
    if (!project) notFound();

    const [deletedReqs, deletedUATs, deletedIssues, deletedTasks] = await Promise.all([
        prisma.requirement.findMany({ where: { projectId: id, deletedAt: { not: null } }, orderBy: { deletedAt: "desc" } }),
        prisma.uATCase.findMany({ where: { projectId: id, deletedAt: { not: null } }, orderBy: { deletedAt: "desc" } }),
        prisma.issue.findMany({ where: { projectId: id, deletedAt: { not: null } }, orderBy: { deletedAt: "desc" } }),
        prisma.task.findMany({ where: { projectId: id, deletedAt: { not: null } }, orderBy: { deletedAt: "desc" } }),
    ]);

    const totalItems = deletedReqs.length + deletedUATs.length + deletedIssues.length + deletedTasks.length;

    const sections = [
        { label: "Requirements", type: "req" as const, items: deletedReqs.map(r => ({ id: r.id, code: r.reqCode, title: r.title, deletedAt: r.deletedAt! })), color: "text-emerald-600 bg-emerald-50 border-emerald-200" },
        { label: "UAT Cases",    type: "uat" as const, items: deletedUATs.map(u => ({ id: u.id, code: u.uatCode, title: u.title, deletedAt: u.deletedAt! })), color: "text-teal-600 bg-teal-50 border-teal-200" },
        { label: "Issues",       type: "issue" as const, items: deletedIssues.map(i => ({ id: i.id, code: i.issueCode, title: i.title, deletedAt: i.deletedAt! })), color: "text-rose-600 bg-rose-50 border-rose-200" },
        { label: "Tasks",        type: "task" as const, items: deletedTasks.map(t => ({ id: t.id, code: "TASK", title: t.title, deletedAt: t.deletedAt! })), color: "text-amber-600 bg-amber-50 border-amber-200" },
    ];

    return (
        <div className="max-w-4xl mx-auto space-y-6 pb-12">
            {/* Header */}
            <div className="bg-white border border-slate-200/80 rounded-3xl shadow-xs p-6 flex items-center gap-4">
                <Link href={`/projects/${id}`} className="p-2.5 hover:bg-slate-100 rounded-2xl text-slate-500 border border-slate-200/60">
                    <ArrowLeft size={18} />
                </Link>
                <div className="p-3.5 bg-rose-50 text-rose-600 rounded-2xl border border-rose-100">
                    <Trash2 size={24} />
                </div>
                <div>
                    <h1 className="text-xl font-extrabold text-slate-800">ถังขยะ (Recycle Bin)</h1>
                    <p className="text-xs text-slate-500 mt-0.5">{project.name} · {project.code} · {totalItems} รายการที่ถูกลบ</p>
                </div>
            </div>

            {totalItems === 0 ? (
                <div className="bg-white border border-slate-200/80 rounded-3xl p-20 text-center">
                    <Trash2 size={48} className="mx-auto mb-4 text-slate-300" />
                    <p className="text-slate-500 font-semibold text-sm">ถังขยะว่างเปล่า</p>
                    <p className="text-slate-400 text-xs mt-1">ไม่มีรายการที่ถูกลบ</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {sections.map(section => section.items.length > 0 && (
                        <div key={section.label} className="bg-white border border-slate-200/80 rounded-2xl shadow-xs overflow-hidden">
                            <div className="px-5 py-3.5 border-b border-slate-100 bg-slate-50/50 flex items-center gap-2">
                                <span className={`text-xs font-extrabold uppercase tracking-wider px-2.5 py-1 rounded-lg border ${section.color}`}>
                                    {section.label}
                                </span>
                                <span className="text-xs text-slate-400 font-medium">{section.items.length} รายการ</span>
                            </div>
                            <div className="divide-y divide-slate-100">
                                {section.items.map(item => (
                                    <div key={item.id} className="flex items-center justify-between px-5 py-3.5 hover:bg-slate-50/60 transition-colors">
                                        <div className="min-w-0 flex-1">
                                            <div className="flex items-center gap-2">
                                                <span className={`text-[11px] font-extrabold ${section.color.split(' ')[0]}`}>{item.code}</span>
                                                <span className="text-sm font-semibold text-slate-700 truncate">{item.title}</span>
                                            </div>
                                            <p className="text-[11px] text-slate-400 mt-0.5 flex items-center gap-1">
                                                <Trash2 size={10} /> ลบเมื่อ {new Date(item.deletedAt).toLocaleString("th-TH")}
                                            </p>
                                        </div>
                                        <TrashActions itemId={item.id} type={section.type} projectId={id} />
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

import { prisma } from "@/lib/prisma";
import Link from "next/link";
import { Plus, FolderKanban, ArrowRight, UserCheck, Users, Shield } from "lucide-react";
import SearchProject from "@/components/SearchProject";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth-options";

export default async function ProjectList({
    searchParams
}: {
    searchParams: Promise<{ q?: string }>
}) {
    const resolvedParams = await searchParams;
    const searchQuery = resolvedParams.q ? resolvedParams.q.trim() : "";

    const session = await getServerSession(authOptions);
    const role = (session?.user as any)?.role;
    const userId = (session?.user as any)?.id;

    let roleWhereCondition: any = {};
    if (role === "PM") {
        roleWhereCondition = { ownerId: userId };
    } else if (role === "DEV") {
        roleWhereCondition = { developers: { some: { id: userId } } };
    }

    const whereCondition: any = {
        ...roleWhereCondition,
    };

    if (searchQuery) {
        whereCondition.OR = [
            { code: { contains: searchQuery, mode: 'insensitive' } },
            { name: { contains: searchQuery, mode: 'insensitive' } },
            { customer: { contains: searchQuery, mode: 'insensitive' } },
        ];
    }

    const projects = await prisma.project.findMany({
        where: whereCondition,
        select: {
            id: true,
            code: true,
            name: true,
            customer: true,
            stage: true,
            progress: true,
            owner: { select: { id: true, name: true } },
            _count: { select: { developers: true } },
        },
        orderBy: { updatedAt: "desc" },
    });

    const getStageStyle = (stage: string) => {
        if (stage === 'DONE' || stage === 'Completed') return 'bg-emerald-50 text-emerald-700 border-emerald-200/80';
        if (stage === 'UAT') return 'bg-teal-50 text-teal-700 border-teal-200/80';
        if (stage === 'DEVELOPMENT') return 'bg-emerald-50 text-emerald-700 border-emerald-200/80';
        return 'bg-amber-50 text-amber-700 border-amber-200/80';
    };

    return (
        <div className="space-y-6 max-w-7xl mx-auto pb-10">
            {/* Header Title Section */}
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-6 rounded-2xl border border-slate-200/80 shadow-xs">
                <div>
                    <h1 className="text-2xl font-extrabold text-slate-800 tracking-tight flex items-center gap-2.5">
                        <FolderKanban className="text-emerald-600" size={26} />
                        Projects Directory
                    </h1>
                    <p className="text-xs text-slate-500 mt-1 flex items-center gap-2">
                        <span>สิทธิ์การใช้งานปัจจุบัน:</span>
                        <span className="inline-flex items-center gap-1 font-bold text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-md border border-emerald-100">
                            <Shield size={12} /> {role}
                        </span>
                    </p>
                </div>

                {role !== "DEV" && (
                    <Link
                        href="/projects/new"
                        prefetch={true}
                        className="flex items-center gap-2 bg-gradient-to-r from-emerald-600 to-green-600 hover:from-emerald-700 hover:to-green-700 text-white px-4 py-2.5 rounded-xl font-semibold text-xs shadow-md shadow-emerald-500/20 transition-all hover:scale-105"
                    >
                        <Plus size={17} />
                        สร้างโครงการใหม่
                    </Link>
                )}
            </div>

            {/* Filter & Search Bar */}
            <div className="bg-white p-4 rounded-2xl border border-slate-200/80 shadow-xs flex items-center justify-between gap-4">
                <SearchProject />
                <div className="text-xs font-bold text-slate-500 hidden sm:block">
                    พบทั้งหมด <strong className="text-emerald-600 font-extrabold text-sm">{projects.length}</strong> โครงการ
                </div>
            </div>

            {/* Projects Table */}
            <div className="bg-white border border-slate-200/80 rounded-2xl shadow-xs overflow-hidden text-sm">
                <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-slate-50/80 text-slate-500 border-b border-slate-200/80 text-xs font-bold uppercase tracking-wider">
                                <th className="px-6 py-4">Project Code</th>
                                <th className="px-6 py-4">Project Name & Customer</th>
                                <th className="px-6 py-4">PM ผู้ดูแล</th>
                                <th className="px-6 py-4">ทีม Developer</th>
                                <th className="px-6 py-4">Stage</th>
                                <th className="px-6 py-4 min-w-[140px]">Progress</th>
                                <th className="px-6 py-4 text-right">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {projects.map((prj) => (
                                <tr key={prj.id} className="hover:bg-emerald-50/30 transition-colors duration-150 group">
                                    <td className="px-6 py-4 font-bold text-emerald-600">
                                        <Link href={`/projects/${prj.id}`} prefetch={true} className="hover:underline flex items-center gap-1.5">
                                            {prj.code}
                                        </Link>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="font-bold text-slate-800 group-hover:text-emerald-700 transition-colors">{prj.name}</div>
                                        <div className="text-xs text-slate-400 mt-0.5">{prj.customer}</div>
                                    </td>
                                    <td className="px-6 py-4 text-slate-700">
                                        {prj.owner ? (
                                            <span className="flex items-center gap-1.5 font-medium text-xs text-slate-700">
                                                <UserCheck size={14} className="text-emerald-500" />
                                                {prj.owner.name}
                                            </span>
                                        ) : (
                                            <span className="text-amber-600 font-semibold text-xs bg-amber-50 px-2 py-0.5 rounded border border-amber-100">
                                                ยังไม่กำหนด PM
                                            </span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-1">
                                            <Users size={14} className="text-slate-400 mr-1" />
                                            <span className="text-xs font-semibold text-slate-600">
                                                {prj._count.developers} คน
                                            </span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={`px-3 py-1 rounded-full text-xs font-bold border ${getStageStyle(prj.stage)}`}>
                                            {prj.stage}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <div className="w-full bg-slate-100 rounded-full h-2 min-w-[70px] overflow-hidden border border-slate-200/50">
                                                <div
                                                    className="h-2 rounded-full bg-gradient-to-r from-emerald-500 to-green-600 transition-all duration-300"
                                                    style={{ width: `${prj.progress}%` }}
                                                ></div>
                                            </div>
                                            <span className="text-xs font-bold text-emerald-600 min-w-[32px]">{prj.progress}%</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <Link
                                            href={`/projects/${prj.id}`}
                                            prefetch={true}
                                            className="inline-flex items-center gap-1 text-xs font-semibold text-emerald-600 hover:text-emerald-800 bg-emerald-50 hover:bg-emerald-100 px-3 py-1.5 rounded-lg transition-colors duration-150"
                                        >
                                            เข้าชม <ArrowRight size={13} />
                                        </Link>
                                    </td>
                                </tr>
                            ))}

                            {projects.length === 0 && (
                                <tr>
                                    <td colSpan={7} className="px-6 py-16 text-center text-slate-400">
                                        <div className="w-16 h-16 rounded-2xl bg-emerald-50 text-emerald-500 flex items-center justify-center mx-auto mb-3">
                                            <FolderKanban size={32} />
                                        </div>
                                        <p className="text-base font-bold text-slate-700">ไม่พบโปรเจกต์ที่คุณมีสิทธิ์เข้าถึง</p>
                                        <span className="text-xs text-slate-400">ลองเปลี่ยนคำค้นหา หรือติดต่อ Admin เพื่อขอสิทธิ์</span>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { FolderKanban, UserPlus, Eye, EyeOff, ArrowRight, CheckCircle2, Loader2 } from "lucide-react";
import Link from "next/link";
import { registerUser } from "@/app/actions/register";
import PasswordStrength from "@/components/PasswordStrength";

const DEPARTMENTS = ["Engineering", "QA", "Design", "Management", "Other"];

export default function RegisterPage() {
    const router = useRouter();
    const [isPending, startTransition] = useTransition();
    const [showPassword, setShowPassword] = useState(false);
    const [success, setSuccess] = useState(false);
    const [error, setError] = useState("");

    const [form, setForm] = useState({
        name: "",
        email: "",
        password: "",
        confirmPassword: "",
        department: "",
        phone: "",
    });

    const update = (key: string, value: string) =>
        setForm((prev) => ({ ...prev, [key]: value }));

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError("");

        // Client-side validation
        if (form.password.length < 6) {
            setError("รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร");
            return;
        }
        if (form.password !== form.confirmPassword) {
            setError("รหัสผ่านไม่ตรงกัน กรุณาตรวจสอบอีกครั้ง");
            return;
        }

        startTransition(async () => {
            const result = await registerUser(form);
            if (result.error) {
                setError(result.error);
            } else {
                setSuccess(true);
            }
        });
    };

    if (success) {
        return (
            <div className="fixed inset-0 flex items-center justify-center bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900 z-[100]">
                <div className="absolute inset-0 overflow-hidden">
                    <div className="absolute -top-40 -right-40 w-96 h-96 bg-emerald-500/10 rounded-full blur-3xl animate-pulse" />
                    <div className="absolute -bottom-40 -left-40 w-96 h-96 bg-green-500/10 rounded-full blur-3xl animate-pulse" style={{ animationDelay: "1s" }} />
                </div>
                <div className="relative bg-white/95 backdrop-blur-xl p-10 rounded-3xl shadow-2xl w-full max-w-md border border-white/20 text-center">
                    <div className="w-16 h-16 mx-auto mb-5 bg-emerald-100 rounded-2xl flex items-center justify-center">
                        <CheckCircle2 size={36} className="text-emerald-600" />
                    </div>
                    <h2 className="text-2xl font-extrabold text-slate-800 mb-2">ลงทะเบียนสำเร็จ!</h2>
                    <p className="text-sm text-slate-500 mb-6 leading-relaxed">
                        บัญชีของคุณถูกสร้างเรียบร้อยแล้ว<br />
                        กรุณารอผู้ดูแลระบบ (Admin) อนุมัติก่อนเข้าสู่ระบบ
                    </p>
                    <Link
                        href="/login"
                        className="inline-flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-emerald-600 to-green-600 hover:from-emerald-700 hover:to-green-700 text-white font-bold text-sm rounded-xl shadow-lg shadow-emerald-500/25 transition-all hover:scale-105"
                    >
                        กลับสู่หน้าเข้าสู่ระบบ <ArrowRight size={16} />
                    </Link>
                </div>
            </div>
        );
    }

    return (
        <div className="fixed inset-0 flex items-center justify-center bg-gradient-to-br from-slate-900 via-emerald-950 to-slate-900 z-[100]">
            {/* Animated background blobs */}
            <div className="absolute inset-0 overflow-hidden">
                <div className="absolute -top-40 -right-40 w-96 h-96 bg-emerald-500/10 rounded-full blur-3xl animate-pulse" />
                <div className="absolute -bottom-40 -left-40 w-96 h-96 bg-green-500/10 rounded-full blur-3xl animate-pulse" style={{ animationDelay: "1s" }} />
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-teal-500/5 rounded-full blur-3xl" />
            </div>

            <div className="relative bg-white/95 backdrop-blur-xl p-8 rounded-3xl shadow-2xl w-full max-w-lg border border-white/20 max-h-[90vh] overflow-y-auto custom-scrollbar">
                {/* Header */}
                <div className="flex flex-col items-center mb-7">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-emerald-500 via-green-600 to-emerald-700 flex items-center justify-center text-white mb-4 shadow-lg shadow-emerald-500/25">
                        <FolderKanban size={28} />
                    </div>
                    <h1 className="text-2xl font-extrabold text-slate-800 tracking-tight">สมัครสมาชิก</h1>
                    <p className="text-sm text-slate-500 mt-1">สร้างบัญชีเพื่อเข้าใช้งาน PM Control Center</p>
                </div>

                {/* Error */}
                {error && (
                    <div className="bg-rose-50 text-rose-600 px-4 py-3 rounded-xl text-sm mb-5 border border-rose-200 font-semibold animate-in slide-in-from-top-2 duration-200">
                        {error}
                    </div>
                )}

                <form onSubmit={handleSubmit} className="space-y-4">
                    {/* Name */}
                    <div>
                        <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1.5">
                            ชื่อ-นามสกุล <span className="text-rose-500">*</span>
                        </label>
                        <input
                            type="text"
                            required
                            value={form.name}
                            onChange={(e) => update("name", e.target.value)}
                            placeholder="เช่น สมชาย ใจดี"
                            className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 focus:bg-white text-sm text-slate-800 font-medium transition-all"
                        />
                    </div>

                    {/* Email */}
                    <div>
                        <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1.5">
