"use client";

import { useState, startTransition } from "react";
import { updateProfile, changePassword, uploadAvatar } from "@/app/actions/user";
import { Save, CheckCircle2, AlertCircle, Camera, User } from "lucide-react";
import { useSession } from "next-auth/react";
import PasswordStrength from "@/components/PasswordStrength";

const DEPARTMENTS = ["Engineering", "QA", "Design", "Management", "Other"];

type UserProps = {
    id: string;
    name: string;
    email: string;
    department: string;
    phone: string;
    avatarUrl: string | null;
};

export default function ProfileForm({ user }: { user: UserProps }) {
    const [name, setName] = useState(user.name);
    const [email, setEmail] = useState(user.email);
    const [department, setDepartment] = useState(user.department);
    const [phone, setPhone] = useState(user.phone);
    const [currentPassword, setCurrentPassword] = useState("");
    const [newPassword, setNewPassword] = useState("");
    const [message, setMessage] = useState("");
    const [error, setError] = useState("");
    const [avatar, setAvatar] = useState(user.avatarUrl);
    const [isUploading, setIsUploading] = useState(false);
    const [isPending, setIsPending] = useState(false);
    const { update } = useSession();

    const handleAvatarChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setIsUploading(true);
        setError("");
        setMessage("");

        try {
            const formData = new FormData();
            formData.append("file", file);

            const result = await uploadAvatar(formData);
            if (result?.avatarUrl) {
                setAvatar(result.avatarUrl);
                await update({ avatarUrl: result.avatarUrl });
                setMessage("อัปโหลดรูปโปรไฟล์เรียบร้อยแล้ว");
                setTimeout(() => setMessage(""), 4000);
            } else if (result?.error) {
                setError(result.error);
            }
        } catch (err: any) {
            setError(err?.message || "เกิดข้อผิดพลาดในการอัปโหลดรูป");
        } finally {
            setIsUploading(false);
        }
    };

    const handleSaveProfile = (e: React.FormEvent) => {
        e.preventDefault();
        setMessage("");
        setError("");
        setIsPending(true);

        startTransition(async () => {
            try {
                const result = await updateProfile(name, email, department, phone);
                if (result?.error) {
                    setError(result.error);
                    setIsPending(false);
                    return;
                }

                if (currentPassword && newPassword) {
                    const passResult = await changePassword(currentPassword, newPassword);
                    if (passResult?.error) {
                        setError(passResult.error);
                        setIsPending(false);
                        return;
                    }
                }

                setCurrentPassword("");
                setNewPassword("");
                setMessage("บันทึกข้อมูลเรียบร้อยแล้ว!");
                setTimeout(() => setMessage(""), 4000);
            } catch (err: any) {
                setError(err?.message || "เกิดข้อผิดพลาด");
            } finally {
                setIsPending(false);
            }
        });
    };

    return (
        <form onSubmit={handleSaveProfile} className="space-y-4 max-w-lg">
            {message && (
                <div className="p-3.5 bg-emerald-50 border border-emerald-200/80 text-emerald-700 text-xs rounded-xl font-bold flex items-center gap-2 animate-in fade-in duration-200">
                    <CheckCircle2 size={16} />
                    <span>{message}</span>
                </div>
            )}
            {error && (
                <div className="p-3.5 bg-rose-50 border border-rose-200/80 text-rose-700 text-xs rounded-xl font-bold flex items-center gap-2 animate-in fade-in duration-200">
                    <AlertCircle size={16} />
                    <span>{error}</span>
                </div>
            )}

            {/* Avatar Upload Section */}
            <div className="flex items-center gap-5 pb-4 border-b border-slate-100">
                <div className="relative group shrink-0">
                    <div className="w-20 h-20 rounded-full overflow-hidden border-4 border-white shadow-md shadow-slate-200/50 bg-slate-100 flex items-center justify-center">
                        {avatar ? (
                            <img src={avatar} alt="Profile" className="w-full h-full object-cover" />
                        ) : (
                            <User size={32} className="text-slate-400" />
                        )}
                    </div>
                    <label className={`absolute inset-0 bg-black/40 rounded-full flex items-center justify-center cursor-pointer opacity-0 group-hover:opacity-100 transition-opacity ${isUploading ? 'opacity-100 cursor-not-allowed' : ''}`}>
                        {isUploading ? (
                            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                        ) : (
                            <Camera size={20} className="text-white" />
                        )}
                        <input type="file" accept="image/*" className="hidden" onChange={handleAvatarChange} disabled={isUploading} />
                    </label>
                </div>
                <div>
                    <h3 className="text-sm font-bold text-slate-800">รูปโปรไฟล์ (Profile Picture)</h3>
                    <p className="text-xs text-slate-500 mt-1">อัปโหลดรูปภาพเพื่อให้ทีมจำคุณได้ง่ายขึ้น</p>
                </div>
            </div>

            <div>
                <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1.5">ชื่อที่แสดง (Display Name)</label>
                <input
                    type="text"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    required
                    className="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 focus:bg-white text-sm text-slate-800 font-medium transition-all"
                />
            </div>

            <div>
                <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1.5">อีเมล / Username</label>
                <input
                    type="text"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    className="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 focus:bg-white text-sm text-slate-800 font-medium transition-all"
                />
            </div>

            {/* Department & Phone */}
            <div className="grid grid-cols-2 gap-3">
                <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1.5">แผนก / Department</label>
                    <select
                        value={department}
                        onChange={(e) => setDepartment(e.target.value)}
                        className="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 focus:bg-white text-sm text-slate-800 font-medium transition-all appearance-none cursor-pointer"
                    >
                        <option value="">-- ไม่ระบุ --</option>
                        {DEPARTMENTS.map((d) => (
                            <option key={d} value={d}>{d}</option>
                        ))}
                    </select>
                </div>
                <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1.5">เบอร์โทร</label>
                    <input
                        type="tel"
                        value={phone}
                        onChange={(e) => setPhone(e.target.value)}
                        placeholder="08x-xxx-xxxx"
                        className="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 focus:bg-white text-sm text-slate-800 font-medium transition-all"
                    />
                </div>
            </div>

            {/* Password Section */}
            <div className="pt-4 border-t border-slate-100 space-y-3">
                <p className="text-xs font-bold uppercase tracking-wider text-slate-500">เปลี่ยนรหัสผ่าน <span className="text-slate-400 font-normal lowercase">(ทิ้งว่างไว้ถ้าไม่ต้องการเปลี่ยน)</span></p>

                <div>
                    <label className="block text-[11px] font-semibold text-slate-400 mb-1">รหัสผ่านปัจจุบัน (Current Password)</label>
                    <input
                        type="password"
                        value={currentPassword}
                        onChange={(e) => setCurrentPassword(e.target.value)}
                        placeholder="กรอกรหัสผ่านปัจจุบัน"
                        className="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 focus:bg-white text-sm text-slate-800 font-medium transition-all"
                    />
                </div>

                <div>
                    <label className="block text-[11px] font-semibold text-slate-400 mb-1">รหัสผ่านใหม่ (New Password)</label>
                    <input
                        type="password"
                        value={newPassword}
                        onChange={(e) => setNewPassword(e.target.value)}
                        placeholder="รหัสผ่านใหม่ (อย่างน้อย 6 ตัวอักษร)"
                        className="w-full px-3.5 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500 focus:bg-white text-sm text-slate-800 font-medium transition-all"
                    />
                    <PasswordStrength password={newPassword} />
                </div>
            </div>

            <div className="pt-2">
                <button
                    type="submit"
                    disabled={isPending}
                    className="bg-gradient-to-r from-emerald-600 to-green-600 hover:from-emerald-700 hover:to-green-700 text-white font-bold text-xs px-6 py-2.5 rounded-xl flex items-center gap-2 shadow-md shadow-emerald-500/20 disabled:opacity-50 transition-all hover:scale-105"
                >
                    <Save size={16} /> {isPending ? "กำลังบันทึก..." : "บันทึกข้อมูล"}
                </button>
            </div>
        </form>
    );
}

import { prisma } from "@/lib/prisma";
import { User, Settings as SettingsIcon, Shield, Bell } from "lucide-react";
import ProfileForm from "./ProfileForm";
import { getAuthUser } from "@/lib/auth";
import Link from "next/link";
import NotificationList from "./NotificationList";

export default async function SettingsPage({ searchParams }: { searchParams: Promise<{ tab?: string }> }) {
    const authUser = await getAuthUser();
    if (!authUser) return <div className="p-8 text-center text-slate-500 font-semibold">กรุณาเข้าสู่ระบบ</div>;

    const user = await prisma.user.findUnique({ where: { id: authUser.id } });
    if (!user) return <div className="p-8 text-center text-slate-500 font-semibold">User not found</div>;

    const resolvedParams = await searchParams;
    const currentTab = resolvedParams.tab || "profile";

    let notifications: any[] = [];
    if (currentTab === "notifications") {
        notifications = await prisma.notification.findMany({
            where: { userId: user.id },
            orderBy: { createdAt: "desc" },
            take: 100
        });
    }

    return (
        <div className="max-w-4xl mx-auto space-y-6 pb-12">
            <div className="bg-white border border-slate-200/80 rounded-3xl shadow-xs p-6 md:p-8 flex items-center gap-4">
                <div className="p-3.5 bg-emerald-50 text-emerald-600 rounded-2xl border border-emerald-100/80 shadow-2xs">
                    <SettingsIcon size={28} />
                </div>
                <div>
                    <h1 className="text-2xl font-extrabold text-slate-800 tracking-tight">System Settings</h1>
                    <p className="text-xs text-slate-500 mt-1">จัดการข้อมูลส่วนตัว, รหัสผ่าน และการตั้งค่าระบบ</p>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                {/* Left Side Menu */}
                <div className="space-y-1.5">
                    <Link href="/settings?tab=profile" className={`w-full flex items-center gap-3 px-4 py-3 font-semibold text-xs rounded-2xl transition-all ${currentTab === "profile" ? "bg-gradient-to-r from-emerald-600 to-green-600 text-white font-bold shadow-md shadow-emerald-500/20" : "text-slate-600 hover:bg-slate-100/80"}`}>
                        <User size={17} /> ข้อมูลส่วนตัว
                    </Link>
                    <Link href="/settings?tab=notifications" className={`w-full flex items-center gap-3 px-4 py-3 font-semibold text-xs rounded-2xl transition-all ${currentTab === "notifications" ? "bg-gradient-to-r from-emerald-600 to-green-600 text-white font-bold shadow-md shadow-emerald-500/20" : "text-slate-600 hover:bg-slate-100/80"}`}>
                        <Bell size={17} /> การแจ้งเตือน
                    </Link>
                    {user.role === "ADMIN" && (
                        <Link href="/admin/users" className="w-full flex items-center gap-3 px-4 py-3 text-slate-600 hover:bg-slate-100/80 font-semibold text-xs rounded-2xl transition-all">
                            <Shield size={17} /> จัดการผู้ใช้งาน (Admin)
                        </Link>
                    )}
                </div>

                {/* Right Side Content Panel */}
                <div className="md:col-span-3 space-y-6">
                    <div className="bg-white border border-slate-200/80 rounded-3xl shadow-xs p-6 md:p-7">
                        {currentTab === "profile" && (
                            <>
                                <h2 className="text-base font-extrabold text-slate-800 border-b border-slate-100 pb-3 mb-5 flex items-center gap-2">
                                    <User size={18} className="text-emerald-600" />
                                    ข้อมูลโปรไฟล์ส่วนตัว (Profile Information)
                                </h2>
                                <ProfileForm user={{
                                    id: user.id,
                                    name: user.name,
                                    email: user.email,
                                    department: user.department ?? "",
                                    phone: user.phone ?? "",
                                    avatarUrl: user.avatarUrl,
                                }} />
                            </>
                        )}
                        {currentTab === "notifications" && (
                            <>
                                <h2 className="text-base font-extrabold text-slate-800 border-b border-slate-100 pb-3 mb-5 flex items-center gap-2">
                                    <Bell size={18} className="text-emerald-600" />
                                    การแจ้งเตือนทั้งหมดของคุณ (Notifications)
                                </h2>
                                <NotificationList initialNotifications={notifications} />
                            </>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

import { prisma } from "@/lib/prisma";
import { Prisma } from "@prisma/client";
import Link from "next/link";
import { CheckSquare, AlertCircle, TestTube, ListTodo, Calendar, ArrowRight } from "lucide-react";
import TaskCheckbox from "@/components/TaskCheckbox";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth-options";
import DeleteTaskButton from "@/components/DeleteTaskButton";

export default async function MyTasksPage() {
    const session = await getServerSession(authOptions);
    const userId = session?.user?.id;
    const role = session?.user?.role || "USER";

    let taskCondition: Prisma.TaskWhereInput = {};
    if (role === "DEV") {
        taskCondition = { assigneeId: userId };
    } else if (role === "PM") {
        taskCondition = {
            OR: [
                { assigneeId: userId },
                { project: { ownerId: userId } }
            ]
        };
    }

    // Parallel fetch all 4 categories in a single round-trip
    const [tasks, assignedIssues, assignedUATs, assignedReqs] = await Promise.all([
        prisma.task.findMany({
            where: { deletedAt: null, ...taskCondition },
            orderBy: [
                { isCompleted: 'asc' },
                { dueDate: 'asc' }
            ],
            include: {
                project: {
                    select: { id: true, name: true, code: true }
                }
            }
        }),
        prisma.issue.findMany({
            where: { assigneeId: userId, deletedAt: null, status: { notIn: ["Resolved", "Closed"] } },
            include: {
                project: {
                    select: { id: true, name: true, code: true }
                }
            }
        }),
        prisma.uATCase.findMany({
            where: { assigneeId: userId, deletedAt: null, status: { notIn: ["Passed"] } },
            include: {
                project: {
                    select: { id: true, name: true, code: true }
                }
            }
        }),
        prisma.requirement.findMany({
            where: { assigneeId: userId, deletedAt: null, status: { notIn: ["Done"] } },
            include: {
                project: {
                    select: { id: true, name: true, code: true }
                }
            }
        })
    ]);

    const pendingTasks = tasks.filter(t => !t.isCompleted);
    const completedTasks = tasks.filter(t => t.isCompleted);

    return (
        <div className="max-w-5xl mx-auto space-y-7 pb-12">
            {/* Title Banner Header */}
            <div className="bg-white border border-slate-200/80 rounded-3xl shadow-xs p-6 md:p-8 flex items-center gap-4">
                <div className="p-3.5 bg-emerald-50 text-emerald-600 rounded-2xl border border-emerald-100/80 shadow-2xs">
                    <CheckSquare size={28} />
                </div>
                <div>
                    <h1 className="text-2xl font-extrabold text-slate-800 tracking-tight">My Tasks & Work Overview</h1>
                    <p className="text-xs text-slate-500 mt-1">รายการงาน, บั๊ก และหน้าที่ทั้งหมดที่คุณได้รับมอบหมาย</p>
                </div>
            </div>

            {/* Assigned Main Modules Section */}
            {(assignedIssues.length > 0 || assignedUATs.length > 0 || assignedReqs.length > 0) && (
                <div className="bg-white border border-slate-200/80 rounded-3xl shadow-xs p-6 md:p-7">
                    <h2 className="text-base font-extrabold text-slate-800 mb-5 border-b border-slate-100 pb-3 flex items-center justify-between">
                        <span>โมดูลหลักที่ได้รับมอบหมาย (Assigned Modules)</span>
                        <span className="text-xs font-bold text-emerald-600 bg-emerald-50 px-3 py-1 rounded-xl">
                            {assignedIssues.length + assignedUATs.length + assignedReqs.length} รายการ
                        </span>
                    </h2>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                        {/* Issues */}
                        {assignedIssues.length > 0 && (
                            <div className="space-y-2.5">
                                <h3 className="text-xs font-extrabold uppercase tracking-wider text-rose-600 flex items-center gap-1.5">
                                    <AlertCircle size={15} /> บั๊กที่ต้องแก้ไข (Issues - {assignedIssues.length})
                                </h3>
                                <div className="space-y-2">
                                    {assignedIssues.map(issue => (
                                        <Link
                                            key={issue.id}
