                                                            <span className="text-slate-400">
                                                                {lastMsg.senderName}:{" "}
                                                            </span>
                                                        ) : null}
                                                        {lastMsg.body}
                                                    </>
                                                ) : (
                                                    <span className="italic text-slate-400">
                                                        ยังไม่มีข้อความ
                                                    </span>
