                            >
                                <Trash2 size={15} />
                                <span>ลบเลย</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* New Chat Modal */}
            <NewChatModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                onRoomCreated={(roomId) => {
                    onRoomCreated(roomId);
                    onSelectRoom(roomId);
                }}
            />
        </aside>
    );
}

